INSERT INTO `announcements` VALUES (1,3,'📢 SCHEDULED WATER INTERRUPTION\n\nMaynilad will have a water interruption this Saturday from 9:00 AM to 4:00 PM. Please store enough water the night before. Salamat po sa pag-unawa!',0,'2026-10-05 00:30:00','2026-10-05 00:30:00'),(2,926,'Reminder: Rent is due on the 1st of every month. You have a 3-day grace period; after that, a one-time 10% late fee is added. Pay in cash at the admin office, or through our official GCash (0917 893 2970, Patricia Joy N.) or BDO account, then upload your proof of payment in the portal.',0,'2026-09-30 00:30:00','2026-09-30 00:30:00'),(3,3,'Fire drill and building inspection next Wednesday, 3:00 PM. Attendance is required for all tenants who are in the building. Please review the evacuation plan posted on every floor (Rules and Regulations, item 12). Comments are turned off for this post.',1,'2026-09-26 00:30:00','2026-09-26 00:30:00');
/*!40000 ALTER TABLE `announcements` ENABLE KEYS */;
