INSERT INTO `dormitory_house_rules` VALUES (78,'A. Conduct and Respect','Treat all tenants, staff, and visitors with respect and consideration. Harassment, discrimination, and bullying are not tolerated.',1,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(79,'A. Conduct and Respect','Quiet hours are 10:00 PM to 6:00 AM. At all other times, tenants must still avoid unreasonable noise that disturbs others.',2,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(80,'A. Conduct and Respect','Curfew is from 11:00 PM to 4:00 AM. Tenants should be inside the dormitory during curfew hours. A tenant who must be out late (for example, because of night work or a class schedule) or expects to return during curfew must inform the management in advance. Emergencies are excepted, and the tenant should inform the management as soon as possible.',3,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(81,'A. Conduct and Respect','Complaints and suggestions to improve the dormitory are welcome and may be sent to the management or through NEST.PH.',4,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(82,'B. Visitors and Room Access','Only registered tenants may enter the rooms. Visitors are received at the receiving area only. Overnight guests are not allowed.',5,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(83,'B. Visitors and Room Access','Tenants are responsible for their visitors and for any loss or damage they cause.',6,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(84,'B. Visitors and Room Access','Management may enter rooms for inspection, maintenance, and safety checks as stated in Section 7 of the Agreement.',7,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(85,'C. Safety and Prohibited Items','Alcoholic beverages, smoking, and vaping are not allowed on the premises.',8,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(86,'C. Safety and Prohibited Items','Hazardous items such as gas, cooking stoves, flammable fuels, and firearms are strictly prohibited. A tenant found using or keeping them may be fined the amount listed in the Payments and Fees Schedule (currently ₱500), and the matter may be reported to the proper authorities where required by law.',9,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(87,'C. Safety and Prohibited Items','Drugs and other illegal substances are strictly prohibited. Possession may be reported to the proper authorities.',10,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(88,'C. Safety and Prohibited Items','Pets are not allowed on the premises.',11,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(89,'C. Safety and Prohibited Items','Do not tamper with fire alarms, extinguishers, or CCTV equipment, and do not block hallways, stairs, or exits. Follow the evacuation plan and staff instructions during a fire, earthquake, or other emergency.',12,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(90,'C. Safety and Prohibited Items','Do not bring or use appliances that draw high power (for example heaters, irons, or cooking appliances) unless the management allows them. Approved appliances may carry an electricity charge listed in the Payments and Fees Schedule.',13,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(91,'C. Safety and Prohibited Items','Cameras (CCTV) may be installed in common areas for safety and security. They are not placed in bedrooms or bathrooms. How footage is used and kept is explained in the Privacy Notice.',14,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(92,'D. Care of the Premises','Keep common areas clean and tidy after use and dispose of garbage in the proper place. Washing clothes in the dormitory is not allowed. A laundry service is available outside the dormitory.',15,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(93,'D. Care of the Premises','Use the air-conditioner only from 10:00 PM to 5:00 AM (aircon schedule), and keep doors and windows closed while it is running.',16,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(94,'D. Care of the Premises','When leaving the room, turn off all faucets, showers, lights, air-conditioners, and other devices. Close and lock the door.',17,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(95,'D. Care of the Premises','Do not move, remove, or swap beds, furniture, or rooms without the management’s approval. Do not transfer or sublet your bed to another person.',18,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(96,'D. Care of the Premises','Report any damage, defect, or unsafe condition promptly to the maintenance staff or through NEST.PH.',19,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(97,'D. Care of the Premises','The tenant pays the reasonable cost of repair or replacement for loss or damage caused by the tenant, the tenant’s visitors, or anyone the tenant is responsible for, as stated in Section 6.3 of the Agreement. Charges follow the Payments and Fees Schedule.',20,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(98,'D. Care of the Premises','If a key is lost or damaged, the tenant pays the key-duplication fee listed in the Payments and Fees Schedule (currently ₱50).',21,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(99,'E. Liability','Tenants must take reasonable care of their belongings and their own safety. The management’s responsibility for loss, damage, or injury is stated in Section 11 of the Agreement. Nothing in these Rules limits any liability that the law does not allow to be limited.',22,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(100,'F. Breach and Disciplinary Steps','For a breach of these Rules, the management will usually follow these steps: (a) verbal reminder; (b) written warning; (c) fine, where one is listed in the Payments and Fees Schedule; and (d) termination under Section 13.2 of the Agreement.',23,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(101,'F. Breach and Disciplinary Steps','The management may skip steps for serious violations, such as illegal drugs, weapons, violence, or conduct that threatens the safety of others. Termination is always subject to the Agreement and Philippine law. The tenant may explain his or her side before a fine or termination is finalized.',24,'2026-10-06 00:00:00','2026-10-06 00:00:00'),(102,'F. Breach and Disciplinary Steps','The management may update these Rules for reasonable administrative, operational, safety, or security reasons, with advance notice to tenants as stated in Section 5.3 of the Agreement.',25,'2026-10-06 00:00:00','2026-10-06 00:00:00');
/*!40000 ALTER TABLE `dormitory_house_rules` ENABLE KEYS */;
UNLOCK TABLES;

