INSERT INTO `floors` VALUES (3,'Ground Floor',0.00,0.00,1,'Lobby, receiving area and study hall. Solo fan rooms and 4-person AC rooms.','2026-07-29 22:22:25','2026-10-06 00:00:00'),(11,'Second Floor',0.00,0.00,2,'4-person and 6-person air-conditioned rooms.','2026-09-04 13:04:53','2026-10-06 00:00:00'),(12,'Third Floor',0.00,0.00,3,'Air-conditioned rooms, including a 12-bed dorm room.','2026-09-29 13:00:54','2026-10-06 00:00:00'),(13,'Fourth Floor',0.00,0.00,4,'6-person room and a 16-bed dorm room.','2026-10-01 15:12:48','2026-10-06 00:00:00'),(14,'Fifth Floor',0.00,0.00,5,'Large dorm room and a 4-person room with a view of the LRT line.','2026-10-01 15:12:48','2026-10-06 00:00:00');
