INSERT INTO `maintenance_tickets` VALUES (1,1,1,NULL,NULL,'Aircon not cooling','maintenance_repairs','The aircon in Room 101 blows air but it is not cold anymore since last night.',NULL,'medium','Standard for this concern type','resolved',928,'2026-09-16 03:50:00',NULL,NULL,'2026-09-18 03:30:00','2026-09-16 03:30:00','2026-09-16 07:30:00'),(2,2,2,NULL,NULL,'Sparking outlet near Bed 2','electrical_issue','The outlet beside my bed sparked when I plugged in my charger. I stopped using it.','[\"demo\\/sample-ticket-photo.png\"]','critical','Sparks, shock or melting · \"sparked\"','open',NULL,NULL,NULL,NULL,NULL,'2026-10-05 22:00:00','2026-10-05 23:00:00'),(3,5,5,NULL,NULL,'Low water pressure in CR','plumbing_water_emergency','Mahina po ang tulo ng tubig sa shower tuwing 6-7 AM.',NULL,'medium','Standard for this concern type','in_progress',928,'2026-10-02 07:50:00',NULL,NULL,NULL,'2026-10-02 07:30:00','2026-10-02 09:30:00'),(4,8,10,NULL,NULL,'Noisy neighbors after quiet hours','noise_roommate_concern','May maingay po sa kabilang room past 12 midnight, 3 nights na. Quiet hours po ay 10 PM.',NULL,'medium','Repeated noise or roommate conflict · \"nights\"','in_progress',NULL,'2026-10-04 02:50:00',NULL,NULL,NULL,'2026-10-04 02:30:00','2026-10-04 03:30:00'),(5,11,15,NULL,NULL,'Request for a bigger study table in the lobby','suggestion_feedback','Suggestion lang po: sana may mas malaking study table sa lobby for group study.',NULL,'low','Standard for this concern type','closed',926,'2026-09-21 05:50:00',NULL,NULL,NULL,'2026-09-21 05:30:00','2026-09-21 07:30:00'),(6,12,16,NULL,NULL,'Question about my rejected GCash payment','billing_payment_concern','Bakit po na-reject yung payment ko? Nagbayad naman po ako.',NULL,'medium','Standard for this concern type','in_progress',927,'2026-10-05 22:20:00',NULL,NULL,NULL,'2026-10-05 22:00:00','2026-10-06 00:00:00'),(7,15,19,NULL,NULL,'Broken door lock','security_concern','Hindi po nagla-lock nang maayos ang pinto ng Room 201, kailangan pang itulak.',NULL,'high','Theft, intruder or broken lock · \"lock\"','resolved',928,'2026-09-27 09:50:00',NULL,NULL,'2026-09-29 09:30:00','2026-09-27 09:30:00','2026-09-27 11:30:00'),(8,18,25,NULL,NULL,'WiFi keeps disconnecting','facilities_amenities','The WiFi on the 2nd floor drops every 10-15 minutes, hard to attend online classes.',NULL,'medium','Standard for this concern type','open',NULL,NULL,NULL,NULL,NULL,'2026-10-05 04:30:00','2026-10-05 05:30:00'),(9,20,29,NULL,NULL,'Ceiling leak near the window','structural_damage','May tumutulo po sa kisame tuwing malakas ang ulan, malapit sa bintana ng Room 204.','[\"demo\\/sample-ticket-photo.png\"]','high','Cracks, leaks or damaged ceiling/floor · \"ceiling leak\"','in_progress',928,'2026-10-03 06:50:00','Roof gutter repair needs 2 dry days; the roofer is booked until the rain stops.','2026-10-09 09:00:00',NULL,'2026-10-03 06:30:00','2026-10-03 09:30:00'),(10,22,36,4,'noise_disturbance','Roommate playing music past quiet hours','tenant_report','Nagpapatugtog po siya ng malakas na music hanggang 1 AM, kahit quiet hours na po ng 10 PM. Hindi po ako makatulog bago ang exam.',NULL,'medium','Repeated noise · \"roommate\"','open',NULL,NULL,NULL,NULL,NULL,'2026-10-05 23:00:00','2026-10-06 00:00:00'),(11,31,50,30,'unauthorized_visitors','Visitor stayed overnight in Room 303','tenant_report','May bisita po siyang lalaki na nag-overnight sa room kagabi. Bawal po ang overnight visitors (Rules and Regulations).',NULL,'high','Standard for this report reason','in_progress',928,'2026-10-04 14:10:00',NULL,NULL,NULL,'2026-10-04 13:25:00','2026-10-04 15:25:00'),(12,11,15,14,'cleanliness_hygiene','Leftover food left in the room','tenant_report','Ilang araw na pong may naiwang pagkain sa table, nagkakaroon na po ng ipis.',NULL,'low','Standard for this report reason','resolved',926,'2026-09-28 14:20:00',NULL,NULL,'2026-09-29 13:35:00','2026-09-28 13:35:00','2026-09-28 16:35:00');
