DROP TABLE IF EXISTS `penalty_audit_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `penalty_audit_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `penalty_id` bigint(20) unsigned NOT NULL,
  `action` enum('created','waived','reinstated') NOT NULL DEFAULT 'created',
  `performed_by` bigint(20) unsigned DEFAULT NULL,
  `reason` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `penalty_audit_logs_penalty_id_foreign` (`penalty_id`),
  KEY `penalty_audit_logs_performed_by_foreign` (`performed_by`),
  CONSTRAINT `penalty_audit_logs_penalty_id_foreign` FOREIGN KEY (`penalty_id`) REFERENCES `penalties` (`id`) ON DELETE CASCADE,
  CONSTRAINT `penalty_audit_logs_performed_by_foreign` FOREIGN KEY (`performed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

