INSERT INTO `ticket_replies` VALUES (1,1,928,NULL,'Noted po. Papupuntahin namin ang technician bukas ng umaga.','2026-09-16 06:30:00'),(2,1,NULL,1,'Salamat po!','2026-09-16 09:30:00'),(3,1,928,NULL,'Nalinis na po ang filter at na-recharge ang freon. Paki-check po kung okay na.','2026-09-16 12:30:00'),(4,3,928,NULL,'Chine-check na po ng plumber ang main line. Update po kami mamaya.','2026-10-02 10:30:00'),(5,5,926,NULL,'Thank you for the suggestion! Hindi po kasya sa space ng lobby sa ngayon, pero isasama namin sa renovation plan next year.','2026-09-21 08:30:00'),(6,6,927,NULL,'Hi Jasmine, naka-crop po kasi yung screenshot kaya hindi makita ang reference number. Paki-upload po ulit yung buong receipt.','2026-10-06 00:00:00'),(7,7,928,NULL,'Napalitan na po ang lock. Paki-kuha po ang bagong susi sa front desk.','2026-09-27 12:30:00'),(8,9,928,NULL,'Na-inspect na po, may crack sa roof gutter. Schedule ang repair ngayong Sabado.','2026-10-03 09:30:00'),(9,9,NULL,20,'Sige po, thank you. Ililipat ko muna yung gamit ko.','2026-10-03 12:30:00'),(10,11,928,NULL,'Salamat po sa report. Kakausapin namin siya at titingnan ang visitor logbook ng guard.','2026-10-04 16:25:00'),(11,12,926,NULL,'Na-remind na po namin si Bea at nalinis na ang area. Paki-report lang po ulit kung maulit.','2026-09-28 16:35:00'),(12,12,NULL,11,'Okay na po, salamat!','2026-09-28 19:35:00');
/*!40000 ALTER TABLE `ticket_replies` ENABLE KEYS */;
UNLOCK TABLES;

